CREATE TABLE tblA(a,b,PRIMARY KEY(a,b)) WITHOUT ROWID; CREATE TABLE tblB(a,b,PRIMARY KEY(a,b)) WITHOUT ROWID; CREATE TABLE tblC(a,b,PRIMARY KEY(a,b)) WITHOUT ROWID; CREATE TRIGGER tr1 BEFORE INSERT ON tblA BEGIN INSERT INTO tblB VALUES(new.a,new.b); END; CREATE TRIGGER tr2 BEFORE INSERT ON tblB BEGIN INSERT INTO tblC VALUES(new.a,new.b); END;